import {ascensionBonuses} from './ascension.js?v=6';
import {runeValue} from './runes.js?v=6';
import {xpNeeded} from './progression.js?v=6';
import {attributeGains} from './attributes.js?v=6';
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
import {CLASSES} from './classes.js?v=6';
export {CLASSES};
export function stats(p){const c=CLASSES[p.classId],lv=p.level-1;let hp=c.hp+lv*(p.classId==='BAS'?44:32),mp=c.mp+lv*3,atk=c.atk+lv*5,def=c.def+lv*3,crit=.12,critd=1.5,acc=1000,haste=0,amp=0,pen=0;for(const id of Object.values(p.equipped)){const i=p.bag.find(v=>v.id===id);if(!i)continue;const e=i.enchant||0;atk+=(i.base.atk||0)*(1+.012*e);def+=(i.base.def||0)*(1+.012*e);hp+=(i.base.hp||0)*(1+.008*e);acc+=(i.base.acc||0)*(1+.006*e);for(const a of i.options||[]){if(a.type==='critd')critd+=a.value;if(a.type==='crit')crit+=a.value;if(a.type==='haste')haste+=a.value;if(a.type==='ampF')amp+=a.value*(p.classId==='ARC'?0:p.classId==='LAS'?.65:1);if(a.type==='ampM')amp+=a.value*(p.classId==='ARC'?1:p.classId==='LAS'?.35:0);if(a.type==='pen'||a.type==='penM')pen+=a.value;if(a.type==='af'||a.type==='am')atk+=a.value;if(a.type==='hp')hp+=a.value;if(a.type==='def')def+=a.value;if(a.type==='precisao')acc+=a.value;}for(const [index,a] of (i.runes||[]).entries()){const value=runeValue(i,a,index);if(a.type==='critd')critd+=value;if(a.type==='crit')crit+=value;if(a.type==='ampF')amp+=value*(p.classId==='ARC'?0:p.classId==='LAS'?.65:1);if(a.type==='ampM')amp+=value*(p.classId==='ARC'?1:p.classId==='LAS'?.35:0);if(a.type==='atk')atk+=value;if(a.type==='hp')hp+=value;if(a.type==='def')def+=value;if(a.type==='pen'||a.type==='penM')pen+=value;if(a.type==='precisao')acc+=value;}}
const wingAura=ascensionBonuses(p);atk*=1+wingAura.attackPct;acc+=wingAura.accuracy;hp*=1+wingAura.hpPct;def*=1+wingAura.defensePct;critd+=wingAura.critd;const growth=attributeGains(p);atk+=growth.attack;def+=growth.def;hp*=1+growth.hpPct;mp=(mp+growth.mp)*(1+growth.mpPct);acc+=growth.accuracy;crit+=growth.crit;haste+=growth.haste;critd+=growth.critd;amp+=growth.magicAmp*(p.classId==='ARC'?1:p.classId==='LAS'?.35:0);const now=Date.now();for(const b of p.buffs||[]){if(b.until<=now)continue;if(b.type==='crit')crit+=.03;if(b.type==='critd')critd+=.05;if(b.type==='hp')hp*=1.05;if(b.type==='def')def*=1.05;if(b.type==='fortress')hp*=1.2;}
crit=clamp(crit,0,.6);critd=clamp(critd,1.5,2.5);haste=clamp(haste,0,.7);amp=clamp(amp,0,.8);const hit=clamp(.85+(acc-p.level*10)/10000,.65,.99),referenceDef=10+.7*p.level**1.35,penetration=(1000+referenceDef)/(1000+Math.max(0,referenceDef-pen)),skillWeight=p.classId==='VIG'?.12:p.classId==='ARC'?.9:.65,offense=atk*12*(1+crit*(critd-1))*(1+haste)*hit/.85*penetration*(1+amp*skillWeight),survival=(def*7+hp*.7)/(1-Math.min(.25,growth.evasion/10000));return {hp:Math.round(hp),mp:Math.round(mp),atk:Math.round(atk),def:Math.round(def),crit:clamp(crit,0,.6),critd:clamp(critd,1.5,2.5),haste:clamp(haste,0,.7),amp:clamp(amp,0,.8),pen,acc,evasion:growth.evasion,pc:Math.round(offense+survival),range:c.range,speed:c.speed,interval:c.interval/(1+haste)};}
export function damage(atk,coef,def,critChance=0,critMult=1.5,rng=Math.random){const critical=rng()<critChance;return {value:Math.max(1,Math.round(atk*coef*1000/(1000+Math.max(0,def))*(critical?critMult:1))),critical};}
export const maxXP=xpNeeded;
export function rollValue(cap,rng=Math.random){const r=rng();let grade=r<.55?60+Math.floor(rng()*151)/10:r<.85?75.1+Math.floor(rng()*150)/10:r<.98?90.1+Math.floor(rng()*99)/10:100;return Math.round(cap*grade/100*10000)/10000;}
let serial=0;export function item(classId,level,slot='weapon',quality='D',rng=Math.random){const c=CLASSES[classId];const names={weapon:c.weapons[0],secondary:c.weapons[1],armor:c.torso,head:'Elmo de '+c.name,hands:'Manoplas de '+c.name,legs:'Perneiras de '+c.name,boots:'Botas de '+c.name};const scale=1+(level-1)*.15;return {id:Date.now().toString(36)+'-'+(++serial),name:names[slot],classId,level,slot,quality,enchant:0,slots:quality==='D'?0:1,runes:[],base:slot==='weapon'?{atk:Math.round((classId==='RUP'?37:25)*scale),acc:classId==='RUP'?120:80}:slot==='secondary'?(classId!=='BAS'?{atk:Math.round(12*scale),acc:40}:{def:Math.round(18*scale),hp:Math.round(60*scale)}):{def:Math.round((slot==='armor'?10:4)*scale),hp:Math.round((slot==='armor'?70:25)*scale)},options:quality==='D'?[]:[{type:classId==='VIG'?'critd':'crit',value:rollValue(classId==='VIG'?.10:.04,rng)}]};}
export function canExtend(playerLevel,i){return playerLevel>=175&&i.level>=175&&['SS+','SSS','SSS+','ULTRA'].includes(i.quality)&&i.slots===2;}
export function potionPulse(current,maxAtUse,maxNow,rate){return Math.min(maxNow,current+maxAtUse*rate/5);}
export function createPlayer(classId,name){const bag=[item(classId,1),...(classId==='RUP'?[]:[item(classId,1,'secondary')]),...['armor','head','hands','legs','boots'].map(slot=>item(classId,1,slot))];return {attributes:{for:0,int:0,des:0},schema:1,name:name.trim().slice(0,18)||'Viajante',classId,level:1,xp:0,gold:5000,progressionVersion:4,materials:{L01:40,E01:10,N01:2,K01:10,P01:10},hp:CLASSES[classId].hp+170+(classId==='BAS'?60:0),mp:CLASSES[classId].mp,x:12,y:14,zone:'coast',bag,equipped:Object.fromEntries(bag.map(i=>[i.slot,i.id])),pots:{hp:6,mp:6},quest:0,kills:0,shards:3,runes:1,buffs:[],dungeonClears:0,killCount:0,playSeconds:0};}
